const random = () => 0.5;
type QidahenDiplomacySelectionSnapshot = ReturnType<typeof getQidahenDiplomacySelectionForCore>;

const testRandom: RandomFn = {
    random: () => 0.5,
    d: () => 4,
    range: (min) => min,
    shuffle: <T>(array: T[]) => [...array],
};

const diceSequence = (...rolls: number[]): RandomFn => {
    let cursor = 0;
    return {
        random: () => 0.5,
        d: () => rolls[cursor++] ?? 4,
        range: (min) => min,
        shuffle: <T>(array: T[]) => [...array],
    };
};

const dieSidesRandom: RandomFn = {
    random: () => 0.5,
    d: (sides) => sides,
    range: (min) => min,
    shuffle: <T>(array: T[]) => [...array],
};

